import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static void skip() {
        while (pos < buf.length && buf[pos] <= ' ') pos++;
    }

    static String next() {
        skip();
        int start = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, start, pos - start);
    }

    static long nextLong() {
        skip();
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] >= '0' && buf[pos] <= '9') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = nextInt();
        String[] words = new String[n];
        String[] pat = new String[n];
        Map<String, Integer> cnt = new HashMap<>();
        for (int i = 0; i < n; i++) {
            words[i] = next();
            // Signature: the signed differences between adjacent letters.
            StringBuilder sb = new StringBuilder();
            for (int j = 0; j + 1 < words[i].length(); j++) sb.append(words[i].charAt(j + 1) - words[i].charAt(j)).append(',');
            pat[i] = sb.toString();
            cnt.merge(pat[i], 1, Integer::sum);
        }
        for (int i = 0; i < n; i++)
            if (cnt.get(pat[i]) == 1) {
                System.out.println(words[i]);
                return;
            }
    }
}

package main

import (
	"fmt"
	"io"
	"os"
	"strings"
)

var data []byte
var pos int

func skip() {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
}

func next() string {
	skip()
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return string(data[start:pos])
}

func nextInt() int64 {
	skip()
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := int(nextInt())
	words := make([]string, n)
	pat := make([]string, n)
	cnt := map[string]int{}
	for i := range words {
		words[i] = next()
		// Signature: the signed differences between adjacent letters.
		var sb strings.Builder
		w := words[i]
		for j := 0; j+1 < len(w); j++ {
			fmt.Fprintf(&sb, "%d,", int(w[j+1])-int(w[j]))
		}
		pat[i] = sb.String()
		cnt[pat[i]]++
	}
	for i := range words {
		if cnt[pat[i]] == 1 {
